-- data/lynch/bursa-hanlar.json noktaları veritabanına taşınır (dosya kaldırıldı; bundan sonra admin panelinden girilir).
-- Ad ve konum OpenStreetMap'ten; belirginlik ekip değerlendirmesi, sahada doğrulanmadı (field_checked = false).
insert into public.nav_points (city_id, title, roles, location, salience, ambient, sort_order, source_note, status, radius_m)
select c.id, v.title, v.roles::public.nav_point_role[], v.location::extensions.geography, v.salience, v.ambient, v.sort_order, v.source_note, 'verified', 25
from public.cities c, (values
  ('{"tr": "Heykel", "en": "Heykel (Atatürk Monument)"}'::jsonb, '{start,landmark}', 'SRID=4326;POINT(29.066882 40.182595)', 3, null, 1, 'Ad ve konum: OpenStreetMap node/1786760959 (ODbL), 14 Ekim 2026. Seçim gerekçesi (ekip): Bursa''nın en bilinen buluşma noktası (Atatürk Heykeli, Cumhuriyet Alanı). T1 Heykel durağı yanında; Atatürk Caddesi''nin doğu ucu.'),
  ('{"tr": "Bursa Kent Müzesi", "en": "Bursa City Museum"}'::jsonb, '{landmark}', 'SRID=4326;POINT(29.0664373 40.1823869)', 3, null, 0, 'Ad ve konum: OpenStreetMap node/1786760093 (ODbL), 14 Ekim 2026. Seçim gerekçesi (ekip): Heykel''deki büyük eski adliye binası; meydanın güney kenarını belirler.'),
  ('{"tr": "T1 Ulucami durağı", "en": "T1 Ulucami tram stop"}'::jsonb, '{start}', 'SRID=4326;POINT(29.062048 40.183498)', null, null, 0, 'Ad ve konum: OpenStreetMap node/4220093466 (ODbL), 14 Ekim 2026. Seçim gerekçesi (ekip): Ulu Cami''ye tramvayla gelenin indiği yer; Atatürk Caddesi üzerinde, caminin hemen güneyi.'),
  ('{"tr": "Koza Parkı", "en": "Koza Park"}'::jsonb, '{start,landmark}', 'SRID=4326;POINT(29.063466 40.183817)', 2, 'water', 3, 'Ad ve konum: OpenStreetMap node/11809341717 (ODbL), 14 Ekim 2026. Seçim gerekçesi (ekip): Koza Hanı ile Orhan Camii arasındaki meydan; ''#Bursa'' yazısı ve süs havuzu. Çarşıya girenlerin buluştuğu yer. Konum yazının OSM noktası; havuz sesi sahada doğrulanmalı.'),
  ('{"tr": "T3 Kozahan durağı", "en": "T3 Kozahan tram stop"}'::jsonb, '{start}', 'SRID=4326;POINT(29.063112 40.185832)', null, null, 4, 'Ad ve konum: OpenStreetMap node/4159778397 (ODbL), 14 Ekim 2026. Seçim gerekçesi (ekip): Hanlar Bölgesi''nin kuzeyinden varış (T3 hattı).'),
  ('{"tr": "T1 Timurtaşpaşa durağı", "en": "T1 Timurtaşpaşa tram stop"}'::jsonb, '{start}', 'SRID=4326;POINT(29.059114 40.184951)', null, null, 5, 'Ad ve konum: OpenStreetMap node/2538045101 (ODbL), 14 Ekim 2026. Seçim gerekçesi (ekip): Batıdan (Tophane, Zafer Plaza tarafı) gelenin indiği durak.'),
  ('{"tr": "Ulucami Otoparkı", "en": "Ulucami car park"}'::jsonb, '{start}', 'SRID=4326;POINT(29.0612387 40.1829425)', null, null, 6, 'Ad ve konum: OpenStreetMap way/999330580 (ODbL), 14 Ekim 2026. Seçim gerekçesi (ekip): Arabayla gelenin başlangıcı; caminin güneybatısı.'),
  ('{"tr": "Tophane Saat Kulesi", "en": "Tophane Clock Tower"}'::jsonb, '{start,landmark}', 'SRID=4326;POINT(29.057576 40.187587)', 3, null, 7, 'Ad ve konum: OpenStreetMap way/253586064 (ODbL), 14 Ekim 2026. Seçim gerekçesi (ekip): Bursa''nın simgelerinden; tepeden görünür. Osman Gazi ve Orhan Gazi türbelerinin yanında, ziyaretçilerin toplandığı teras.'),
  ('{"tr": "Zafer Plaza", "en": "Zafer Plaza"}'::jsonb, '{start,landmark}', 'SRID=4326;POINT(29.0595272 40.1875729)', 3, null, 8, 'Ad ve konum: OpenStreetMap way/26470681 (ODbL), 14 Ekim 2026. Seçim gerekçesi (ekip): Cam piramidiyle uzaktan seçilen alışveriş merkezi; gençlerin bilinen buluşma noktası.'),
  ('{"tr": "Eski Aynalı Çarşı", "en": "Old Mirrored Bazaar"}'::jsonb, '{landmark}', 'SRID=4326;POINT(29.06294 40.184496)', 2, 'market', 0, 'Ad ve konum: OpenStreetMap way/1156644734 (ODbL), 14 Ekim 2026. Seçim gerekçesi (ekip): Orhan Bey Hamamı''nın çarşıya dönüşmüş yapısı; Kapalıçarşı''nın tanınan girişlerinden. Çarşı uğultusu.'),
  ('{"tr": "Kapalıçarşı", "en": "Covered Bazaar"}'::jsonb, '{landmark}', 'SRID=4326;POINT(29.0626823 40.1845383)', 2, 'market', 0, 'Ad ve konum: OpenStreetMap way/1156644736 (ODbL), 14 Ekim 2026. Seçim gerekçesi (ekip): Ulu Cami ile hanlar arasındaki kapalı çarşı; içinden geçen her rota için güçlü bir ses ve doku değişimi.'),
  ('{"tr": "Timurtaş Paşa Türbesi", "en": "Tomb of Timurtaş Paşa"}'::jsonb, '{landmark}', 'SRID=4326;POINT(29.059229 40.184463)', 2, null, 0, 'Ad ve konum: OpenStreetMap way/834673962 (ODbL), 14 Ekim 2026. Seçim gerekçesi (ekip): Atatürk Caddesi ile Cemal Nadir Caddesi ayrımında, durağın yanında; batıdan gelenin ilk tarihî yer işareti.')
) as v(title, roles, location, salience, ambient, sort_order, source_note)
where c.slug = 'bursa';
